class Solution {
public:
    int minimumFinishTime(vector<vector<int>>& tires, int changeTime, int numLaps) {
        const long long INF=LLONG_MAX/4;
        vector<long long> best(numLaps+1,INF);
        for(auto &t:tires) {
            long long lap=t[0],sum=0;
            for(int j=1;j<=numLaps && lap<=t[0]+changeTime;++j) {
                sum+=lap;best[j]=min(best[j],sum);
                if(lap>INF/t[1]) break;
                lap*=t[1];
            }
        }
        vector<long long> dp(numLaps+1,INF);dp[0]=-changeTime;
        for(int i=1;i<=numLaps;++i)
            for(int j=1;j<=i && best[j]<INF;++j)
                dp[i]=min(dp[i],dp[i-j]+changeTime+best[j]);
        return (int)dp[numLaps];
    }
};
